fn solve(coins: Vec<i8>) -> i8 {
    // Compute the sum in a wider integer type to avoid overflow
    let sum: i32 = coins.into_iter().map(i32::from).sum();
    
    // Check if the sum is strictly positive and divisible by 5
    if sum > 0 && sum % 5 == 0 {
        // Safe to cast back to i8 because (0..=500)/5 == 0..=100
        (sum / 5) as i8
    } else {
        -1
    }
}

